def blog(slug,title,focus,artifact,owner,tests):
 p=[f'# {title}\n\n**Published: {VD}**\n\n{title} matters when {focus} changes what a customer hears, what an agent records, and what a client may safely conclude. The control is not a polished disposition; it is a traceable outcome that separates verified events from interpretation, preserves uncertainty, and gives the next decision to a named owner. The working artifact is a {artifact}, maintained by the {owner}.']
 steps=[('Set the operating boundary','state the trigger, permitted action, prohibited decision, and customer-safe promise'),('Design the evidence packet','capture source time, queue, interaction identifier, observed state, agent action, owner, due point, and correction history'),('Write the customer response','explain what is known, what remains uncertain, and when the next update will occur'),('Test ordinary and adverse paths',f'exercise an ordinary case plus {tests}'),('Route exceptions deliberately','require a receiving role, minimum packet, acknowledgement state, and return path'),('Review quality in context','compare the source interaction with the record so a tidy label cannot hide missing proof'),('Close and improve','require observable closure, retain corrections, change one control, and schedule a retest')]
 for i,(h,a) in enumerate(steps,1):
  p.append(f'''## {h}\n\nFor {focus}, the team should {a}. Label this checkpoint CCO13-{slug}-{i}. The identifier connects the event, exception, response, receiving owner, and acceptance without copying unnecessary customer data. The {owner} owns control design; an agent owns only the bounded action in the current procedure.\n\nDuring {h.lower()}, simulate {tests}. Read the exact customer wording beside the system event and receiving-owner acknowledgement. A pass requires evidence for the claimed outcome, an owned next step, and a timestamp another reviewer can follow. A failure stays open with a reason and due point; ending the call or selecting a favorable disposition does not turn incomplete evidence into success.\n\nUse the {artifact} as the review surface for {h.lower()}. Preserve the first observation and append a correction instead of overwriting it. If tools disagree, label the conflict, restrict the promise to what is verified, and route the decision to the {owner}. This creates a defensible handoff and reveals recurring patterns without asking frontline staff to invent policy.''')
 p.append(f'''## Acceptance checklist\n\n- State why {focus} is recorded before collecting extra information.\n- Keep verified facts separate from interpretation.\n- Name the {owner} for unresolved exceptions.\n- Retest after a script, route, or system change.\n- Preserve corrections and closure evidence.\n\n## Related guidance\n\n[Browse call center operating articles](/blog)\n\n[Review source-backed call center research](/research)\n\n[Plan the related service workflow](/services/inbound-customer-care)\n\n## Plan the boundary\n\n[Discuss a Philippines-based call center workflow](/contact-us) with the queue, systems, customer promise, restricted decisions, and exception owner identified.''')
 return '\n\n'.join(p)+'\n'
def rr(n,slug,title,focus,question,owner):
 secs=[]
 for j,h in enumerate(H,1):
  secs.append({'heading':h,'paragraphs':[
   {'text':f'For {focus}, {h.lower()} examines {question}. Observation CCO13-R-{n}-{j} follows one selected interaction or drill from the first source event through agent action, customer-visible effect, exception routing, and final acknowledgement. Record the selection query, period, channel, tool version, evidence available at the decision point, missing fields, correction history, and accountable owner so another reviewer can reconstruct the result.','citations':[j%10+1,(j+3)%10+1]},
   {'text':f'The {owner} should compare ordinary, ambiguous, conflicting, unavailable-system, and high-consequence cases during {h.lower()}. Preserve unknown values and reviewer disagreements rather than forcing them into a favorable category. Public guidance supplies control concepts, but cannot certify this queue, prove provider-wide performance, establish legal compliance, or substitute for current advice and accountable client decisions.','citations':[(j+1)%10+1,(j+5)%10+1]},
   {'text':f'A reproducible result for {focus} at the {h.lower()} stage includes inclusion and exclusion rules, synthetic fixtures, reviewer identity, source timestamps, correction history, denominator logic, and a stop rule. Report every numerator with its denominator and inspect records before changing scripts, access, staffing, or routing. Any proposed change receives one owner, one expected customer effect, and a dated retest.','citations':[(j+2)%10+1,(j+7)%10+1]}]})
 prose=' '.join(p['text'] for s in secs for p in s['paragraphs'])
 return {'slug':slug,'hero':f'/oct13-heroes/{slug}.webp','title':title,'excerpt':f'A source-bounded study of {focus}, evidence limits, adverse controls, and accountable decisions.','published':D,'modified':D,'revision':f'{D}-{slug}-v1','readingMinutes':16,'wordCount':wc(prose),'methodology':f'This report maps ten authoritative HTTPS sources to one bounded question about {focus}. It fixes the observation unit before collection, includes ordinary and adverse controls, preserves missing evidence, requires an independently reviewed subset, and separates observed events from interpretation. Sources were reviewed for publication on {VD}.','limitations':f'This is a design and evidence review about {focus}, not legal advice, certification, a provider benchmark, or proof of causation. Findings remain bounded to the named queue, period, systems, definitions, records, and reviewer access. Requirements can change; the {owner} must confirm them before release.','keyTakeaways':[f'Define {focus} before sampling.','Preserve missing and conflicting evidence.',f'Keep consequential decisions with the {owner}.'],'stats':[{'value':'1','label':'bounded observation unit','note':'Follow one event through observable closure.','source':1},{'value':'5','label':'control states','note':'Include ordinary, ambiguous, conflicting, unavailable, and high-consequence cases.','source':3},{'value':'10','label':'authoritative sources','note':'Use guidance as input, not performance proof.','source':9}],'sections':secs,'table':{'caption':f'Evidence states for {focus}','headers':['State','Evidence','Disposition'],'rows':[['Ordinary','Complete source and acknowledgement','Bounded finding'],['Ambiguous','Conflicting or incomplete signals','Remain unknown'],['Adverse','Synthetic failure and response','Route and retest']]},'buyerChecklist':[f'Define the unit for {focus}.','Name the accountable owner.','Lock denominator rules.','Preserve unknown states.','Retest one change.'],'contextualService':{'heading':'Apply evidence carefully','href':'/services/reporting-and-quality-assurance','label':'Plan a controlled QA workflow','text':'Use a bounded pilot with client-owned decisions.'},'faqs':[{'q':f'Does this prove performance for {focus}?','a':'No. It defines a reproducible review and bounded interpretation.'},{'q':'How is missing evidence counted?','a':'Keep it missing or unknown; never silently convert it to a pass.'},{'q':'Who approves a change?','a':f'The client-side {owner} approves and schedules the retest.'}],'related':[{'title':'Operating guides','href':'/blog'},{'title':'Research library','href':'/research'},{'title':'Discuss a pilot','href':'/contact-us'}],'sources':[{'name':a,'url':u,'note':'Authoritative public guidance used as a bounded control input.','kind':'Global comparison'} for a,u in SRC]}
